package android.os; import java.util.*; public final class Handler { public static long uptime; private static final ArrayList<Entry> entries=new ArrayList<>(); private static class Entry { Runnable r; long at; Entry(Runnable r,long at){this.r=r;this.at=at;} } public Handler(Looper l){} public boolean post(Runnable r){return postDelayed(r,0);} public boolean postDelayed(Runnable r,long delay){entries.add(new Entry(r,uptime+delay));return true;} public void removeCallbacks(Runnable r){entries.removeIf(e->e.r==r);} public static void drain(){int n=0; while(true){Entry next=null;for(Entry e:entries){if(e.at<=uptime&&(next==null||e.at<next.at))next=e;} if(next==null)return;if(++n>1000)throw new AssertionError("runaway handler");entries.remove(next);next.r.run();}} public static void advance(long ms){uptime+=ms;SystemClock.now+=ms;drain();} public static void reset(){entries.clear();uptime=0;SystemClock.now=0;} public static int size(){return entries.size();} }